CREATE OR REPLACE FUNCTION public.validate_user_habit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE lim integer:=3; BEGIN IF EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND is_demo) THEN lim:=8; END IF; IF NEW.active AND (SELECT count(*) FROM public.user_habits WHERE user_id=NEW.user_id AND season_id=NEW.season_id AND active AND id<>NEW.id)>=lim THEN RAISE EXCEPTION 'max_habits'; END IF; IF NEW.custom_name IS NOT NULL AND length(NEW.custom_name)>40 THEN RAISE EXCEPTION 'name_too_long'; END IF; RETURN NEW; END $$;